const acorn=require('acorn'),base=require('./standard236.json');
exports.restore=code=>{code=require('./normal238.cjs').restore(code);const start=code.indexOf('// TEST237:');if(start>=0)code=code.slice(0,start)+base.catalog+code.slice(code.indexOf('function normalCardsForDeck',start));const p=acorn.parse(code,{ecmaVersion:'latest'}),nodes=[...p.body[0].expression.callee.body.body,...p.body.slice(1)];for(const n of nodes.sort((a,b)=>b.start-a.start)){const key=n.id?.name||n.declarations?.map(d=>d.id.name).join(',')||'';if(base.functions[key])code=code.slice(0,n.start)+base.functions[key]+code.slice(n.end)}return code};
